//! FlatBuffers competitor.
//!
//! The accessors below are **generated by `flatc`** (see `../../fbs/*.fbs`),
//! not hand written. Regenerate with:
//!
//! ```text
//! cd crates/slim-bench/fbs && flatc --rust -o ../src/flat *.fbs
//! ```
//!
//! Version pairing (decision D-0003): the installed compiler is
//! `flatc version 2.0.8` and it emits code that only compiles against the
//! 2.x runtime (`flatbuffers 2.1.2` is the newest 2.x published). The newest
//! published runtime, `flatbuffers 25.12.19`, has an incompatible API
//! (`Follow::follow` and `Table::get` became `unsafe`), so the newest pair
//! that actually compiles is 2.0.8 + 2.1.2.
//!
//! Verified vs unverified reads both come from the generated code:
//! `root_as_telemetry` verifies, `root_as_telemetry_unchecked` does not.
//! The measurement protocol never compares a verified read against an
//! unverified one.

#![allow(dead_code)]

use flatbuffers::FlatBufferBuilder;

// `flatc` output is not clippy-clean; it is machine generated and never edited
// by hand.
#[allow(unused_imports, mismatched_lifetime_syntaxes, clippy::all)]
#[path = "telemetry_generated.rs"]
pub mod telemetry_generated;
#[allow(unused_imports, mismatched_lifetime_syntaxes, clippy::all)]
#[path = "telemetry_small_generated.rs"]
pub mod telemetry_small_generated;

use telemetry_generated::slim_bench::fb::TelemetryBuilder;
use telemetry_small_generated::slim_bench::fb::{
    finish_telemetry_small_buffer, root_as_telemetry_small, root_as_telemetry_small_unchecked,
    TelemetrySmallBuilder,
};

use crate::datasets::{Telemetry, TelemetrySmall};

/// Builds one `TelemetrySmall` FlatBuffer (cold: fresh builder).
pub fn build_telemetry_small(record: &TelemetrySmall) -> Vec<u8> {
    let mut fbb = FlatBufferBuilder::new();
    let mut b = TelemetrySmallBuilder::new(&mut fbb);
    b.add_rsrp(record.rsrp);
    b.add_band(record.band);
    b.add_speed(record.speed);
    let off = b.finish();
    finish_telemetry_small_buffer(&mut fbb, off);
    fbb.finished_data().to_vec()
}

/// Verified zero-copy read of one `TelemetrySmall` FlatBuffer.
pub fn read_telemetry_small_verified(
    bytes: &[u8],
) -> Result<TelemetrySmall, flatbuffers::InvalidFlatbuffer> {
    let t = root_as_telemetry_small(bytes)?;
    Ok(TelemetrySmall {
        rsrp: t.rsrp(),
        band: t.band(),
        speed: t.speed(),
    })
}

/// Unverified zero-copy read of one `TelemetrySmall` FlatBuffer.
///
/// # Safety
/// The caller must guarantee `bytes` is a well-formed FlatBuffer produced by
/// the matching builder; FlatBuffers' own `_unchecked` accessor is `unsafe`.
pub unsafe fn read_telemetry_small_unverified(bytes: &[u8]) -> TelemetrySmall {
    let t = root_as_telemetry_small_unchecked(bytes);
    TelemetrySmall {
        rsrp: t.rsrp(),
        band: t.band(),
        speed: t.speed(),
    }
}

/// Builds a vector of `Telemetry` tables (batch shape used by W1).
pub fn build_telemetry_batch(records: &[Telemetry]) -> Vec<u8> {
    let mut fbb = FlatBufferBuilder::new();
    let mut offsets = Vec::with_capacity(records.len());
    for r in records {
        let mut b = TelemetryBuilder::new(&mut fbb);
        b.add_rsrp(r.rsrp);
        b.add_band(r.band);
        b.add_speed(r.speed);
        b.add_timestamp(r.timestamp);
        b.add_cell_id(r.cell_id);
        offsets.push(b.finish());
    }
    let vec = fbb.create_vector(&offsets);
    fbb.finish_minimal(vec);
    fbb.finished_data().to_vec()
}

/// Verified zero-copy read of a `Telemetry` vector built by
/// [`build_telemetry_batch`].
pub fn read_telemetry_batch_verified(
    bytes: &[u8],
) -> Result<Vec<Telemetry>, flatbuffers::InvalidFlatbuffer> {
    type FbTelemetry<'a> = telemetry_generated::slim_bench::fb::Telemetry<'a>;
    let v = flatbuffers::root::<
        flatbuffers::Vector<'_, flatbuffers::ForwardsUOffset<FbTelemetry<'_>>>,
    >(bytes)?;
    Ok(v.iter()
        .map(|t| Telemetry {
            rsrp: t.rsrp(),
            band: t.band(),
            speed: t.speed(),
            timestamp: t.timestamp(),
            cell_id: t.cell_id(),
        })
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn small() -> TelemetrySmall {
        TelemetrySmall {
            rsrp: -97,
            band: 3,
            speed: 42.5,
        }
    }

    fn telemetry() -> Telemetry {
        Telemetry {
            rsrp: -101,
            band: 7,
            speed: 13.25,
            timestamp: 1_700_000_000_123,
            cell_id: 424_242,
        }
    }

    #[test]
    fn telemetry_small_round_trips() {
        let bytes = build_telemetry_small(&small());
        assert_eq!(read_telemetry_small_verified(&bytes).unwrap(), small());
        // SAFETY: `bytes` was just produced by `build_telemetry_small`.
        assert_eq!(unsafe { read_telemetry_small_unverified(&bytes) }, small());
    }

    #[test]
    fn telemetry_batch_round_trips() {
        let rows = vec![telemetry(), telemetry(), telemetry()];
        let bytes = build_telemetry_batch(&rows);
        assert_eq!(read_telemetry_batch_verified(&bytes).unwrap(), rows);
    }

    #[test]
    fn verifier_rejects_truncated_and_random_bytes() {
        let bytes = build_telemetry_small(&small());
        assert!(read_telemetry_small_verified(&bytes[..bytes.len() - 2]).is_err());
        assert!(read_telemetry_small_verified(&[]).is_err());
        assert!(read_telemetry_small_verified(&[0xff; 32]).is_err());
    }
}
